import {
  type AssistantMessage,
  type ContextEdit,
  type ContextItem,
  type ContextView,
  ELIDED_CALLS_PREFIX,
  ELIDED_PREFIX,
  type EditProvenance,
  type Message,
  messageTokens,
  SUMMARY_PREFIX,
} from "./view.js";

export const MAX_EDIT_TARGETS = 200;
export const MAX_REASON_CHARS = 200;

/** A rewrite ready to write: the edits and what Pit records about them. */
export interface PlannedEdit {
  edits: ContextEdit[];
  provenance: EditProvenance;
}

export interface PlannedSummary extends PlannedEdit {
  summarizedEntries: number;
  summaryTokens: number;
}

export function formatTokens(tokens: number): string {
  return tokens >= 1_000 ? `${(tokens / 1_000).toFixed(1)}K` : String(tokens);
}

function textMessage(original: Message, text: string): Message {
  if (original.role === "assistant") {
    // No tool calls remain, so the turn reads as one that stopped.
    return { ...original, content: [{ type: "text", text }], stopReason: "stop" };
  }
  return { ...original, content: [{ type: "text", text }] } as Message;
}

function requireEditable(view: ContextView, id: string): ContextItem {
  const item = view.byId.get(id);
  if (!item) {
    throw new Error(
      view.activeIds.has(id)
        ? `Entry ${id} contributes nothing to the context`
        : `Entry ${id} is not in the active context`,
    );
  }
  if (item.protectedReason) {
    throw new Error(`Entry ${id} cannot be edited: ${item.protectedReason}`);
  }
  if (item.state !== "original") throw new Error(`Entry ${id} is already ${item.state}`);
  if (view.pending.has(id)) throw new Error(`Entry ${id} already has a staged rewrite`);
  return item;
}

function callResults(view: ContextView, item: ContextItem): ContextItem[] {
  return item.toolCallIds.flatMap((id) => {
    const result = view.results.get(id);
    return result ? [result] : [];
  });
}

/** The note that replaces an elided entry's tool calls and their results, as on Pi. */
function callNote(item: ContextItem, results: ContextItem[], reason?: string): string {
  const names = item.tools;
  const tokens = item.tokens + results.reduce((sum, result) => sum + result.tokens, 0);
  const failed = results.filter(
    (result) => (result.messages[0] as { isError?: boolean }).isError === true,
  ).length;
  const label =
    names.length === 1
      ? `${ELIDED_CALLS_PREFIX}: ${names[0]}`
      : `${ELIDED_CALLS_PREFIX}s: ${names.join(", ")}`;
  const withResults =
    results.length === 0 ? "" : results.length === 1 ? " with its result" : " with their results";
  const parts = [
    `${label} · ~${formatTokens(tokens)} tokens${withResults}`,
    ...(failed > 0 ? [`${failed} failed`] : []),
    ...(reason ? [`reason: ${reason}`] : []),
    `originals: ${[item.id, ...results.map((result) => result.id)].map((id) => `session.inspectEntry("${id}")`).join(", ")}`,
  ];
  return `${parts.join(" · ")}]`;
}

export function elisionStub(id: string, tokens: number, reason?: string): string {
  const because = reason ? ` · reason: ${reason}` : "";
  return `${ELIDED_PREFIX} · ~${formatTokens(tokens)} tokens${because} · original: session.inspectEntry("${id}")]`;
}

function checkReason(reason: string | undefined): void {
  if (reason !== undefined && reason.length > MAX_REASON_CHARS) {
    throw new Error(`reason must be at most ${MAX_REASON_CHARS} characters`);
  }
}

/**
 * Elide entries. A tool result keeps its place, so its call stays answered, and shows a stub. An
 * assistant entry's tool calls become a plain-text note, and their results leave the context with
 * them, so the model sees neither a call to copy nor an unanswered one.
 */
export function planElide(view: ContextView, ids: readonly string[], reason?: string): PlannedEdit {
  checkReason(reason);
  if (ids.length === 0) throw new Error("elide needs at least one entry ID");
  if (ids.length > MAX_EDIT_TARGETS) {
    throw new Error(`elide takes at most ${MAX_EDIT_TARGETS} entries per call`);
  }
  const unique = [...new Set(ids)];
  // Results whose call is elided too leave with their call's note.
  const answered = new Set(
    unique.flatMap((id) => {
      const item = view.byId.get(id);
      return item?.role === "assistant" ? callResults(view, item).map((result) => result.id) : [];
    }),
  );
  const edits: ContextEdit[] = [];
  let tokensFreed = 0;
  for (const id of unique) {
    const item = requireEditable(view, id);
    const message = item.messages[0] as Message;
    if (item.role === "assistant" && item.toolCallIds.length > 0) {
      // Results follow their call, so they are editable when it is.
      const results = callResults(view, item);
      const note = callNote(item, results, reason);
      edits.push({
        target: item.entry.id,
        action: "replace",
        messages: [textMessage(message as AssistantMessage, note)],
      });
      for (const result of results) edits.push({ target: result.entry.id, action: "omit" });
      const kept = messageTokens(textMessage(message, note));
      tokensFreed += item.tokens + results.reduce((sum, result) => sum + result.tokens, 0) - kept;
      continue;
    }
    if (answered.has(item.id)) continue;
    const stub = elisionStub(id, item.tokens, reason);
    const replacement = textMessage(message, stub);
    edits.push({ target: item.entry.id, action: "replace", messages: [replacement] });
    tokensFreed += item.tokens - messageTokens(replacement);
  }
  return {
    edits,
    provenance: {
      operation: "elide",
      targets: unique,
      covers: edits.map((edit) => String(edit.target)),
      ...(reason ? { reason } : {}),
      tokensFreed: Math.max(0, tokensFreed),
    },
  };
}

/**
 * Replace a contiguous range with a summary: its first entry carries the summary and the rest leave
 * the context. A range must keep each tool call with its result.
 */
export function planSummarize(
  view: ContextView,
  input: { from: string; to: string; summary: string },
): PlannedSummary {
  const start = view.items.findIndex((item) => item.id === input.from);
  const end = view.items.findIndex((item) => item.id === input.to);
  if (start === -1) throw new Error(`Entry ${input.from} is not visible in the active context`);
  if (end === -1) throw new Error(`Entry ${input.to} is not visible in the active context`);
  if (end < start) throw new Error(`Entry ${input.from} comes after ${input.to}`);
  if (input.summary.trim() === "") throw new Error("summary must not be empty");
  const range = view.items.slice(start, end + 1);
  for (const item of range) requireEditable(view, item.id);
  const inRange = new Set(range.map((item) => item.id));
  for (const item of range) {
    for (const call of item.toolCallIds) {
      const partner =
        item.role === "toolResult"
          ? view.items.find(
              (candidate) => candidate.role === "assistant" && candidate.toolCallIds.includes(call),
            )
          : view.results.get(call);
      if (partner && !inRange.has(partner.id)) {
        throw new Error(
          `The range splits tool call ${call}: entries ${item.id} and ${partner.id} must both be in it or both outside`,
        );
      }
    }
  }
  const carrier = range[0] as ContextItem;
  const header = `${SUMMARY_PREFIX}${range.length} entries from ${input.from} to ${input.to} · originals: session.inspectEntry(id)]`;
  const replacement = textMessage(carrier.messages[0] as Message, `${header}\n${input.summary}`);
  const replacedTokens = range.reduce((sum, item) => sum + item.tokens, 0);
  const summaryTokens = messageTokens(replacement);
  if (summaryTokens >= replacedTokens) {
    throw new Error(
      `The summary (~${formatTokens(summaryTokens)} tokens) must be shorter than the ~${formatTokens(replacedTokens)} tokens it replaces`,
    );
  }
  return {
    edits: [
      { target: carrier.entry.id, action: "replace", messages: [replacement] },
      ...range.slice(1).map((item) => ({ target: item.entry.id, action: "omit" as const })),
    ],
    provenance: {
      operation: "summarize",
      targets: [input.from, input.to],
      carrier: carrier.id,
      covers: range.map((item) => item.id),
      tokensFreed: replacedTokens - summaryTokens,
    },
    summarizedEntries: range.length,
    summaryTokens,
  };
}

=== src/durable/context/staging.ts
import type { ToolExecutionApi } from "@earendil-works/pi-durable";

import { type EditTiming, writeEdit } from "./apply.js";
import type { PlannedEdit } from "./edits.js";
import { applyNoteChanges, changeNote } from "./notes.js";
import type { ContextView } from "./view.js";

type ToolContext = Parameters<ToolExecutionApi["commit"]>[1];
type NoteList = Parameters<typeof changeNote>[0];

/**
 * The context changes one `typescript` call staged. As on Pi, they apply only if the call
 * succeeds: the tool applies them after the program and its saved-function changes, and drops
 * them when the program fails.
 */
export class StagedContextChanges {
  readonly #edits: Array<{ plan: PlannedEdit; timing: EditTiming }> = [];
  readonly #notes: Array<{ key: string; content: string | null }> = [];

  /** The view with this call's staged targets marked pending, so a target is staged once. */
  withPending(view: ContextView): ContextView {
    const pending = new Map(view.pending);
    for (const { plan } of this.#edits) {
      for (const target of plan.provenance.covers) pending.set(target, plan.provenance.operation);
    }
    return { ...view, pending };
  }

  stageEdit(plan: PlannedEdit, timing: EditTiming): void {
    this.#edits.push({ plan, timing });
  }

  /** Validates a note change against the notes as this call left them, then stages it. */
  stageNote(
    current: Readonly<{ notes: Readonly<NoteList> }>,
    change: { key: string; content: string | null; contextWindow: number | undefined },
  ) {
    const notes = this.notes(current);
    const result = changeNote(notes, change);
    this.#notes.push({ key: change.key, content: change.content });
    return result;
  }

  /** The notes with this call's staged changes applied. */
  notes(current: Readonly<{ notes: Readonly<NoteList> }>): NoteList {
    const notes = current.notes.map((note) => ({ ...note }));
    for (const change of this.#notes) {
      changeNote(notes, { ...change, contextWindow: Number.POSITIVE_INFINITY });
    }
    return notes;
  }

  /** Keys this call staged a change for. */
  pendingNotes(): ReadonlySet<string> {
    return new Set(this.#notes.map(({ key }) => key));
  }

  /** Writes what the call staged: notes first, then each rewrite in call order. */
  async apply(
    api: Pick<ToolExecutionApi, "commit" | "conversation" | "conversationId">,
    context: ToolContext,
    contextWindow: number | undefined,
  ): Promise<void> {
    if (this.#notes.length > 0) {
      await applyNoteChanges(api, context, this.#notes, contextWindow);
    }
    for (const { plan, timing } of this.#edits) await writeEdit(api, context, plan, timing);
  }
}

=== src/durable/context/view.ts
import type { ToolExecutionApi } from "@earendil-works/pi-durable";

export type Tx = Parameters<Parameters<ToolExecutionApi["commit"]>[0]>[0];
export type EntryRecord = Awaited<ReturnType<Tx["scanEntries"]>>["items"][number];
export type EntryId = EntryRecord["id"];
export type Message = NonNullable<EntryRecord["model"]>[number];
export type AssistantMessage = Extract<Message, { role: "assistant" }>;
export type ContextEdit = NonNullable<EntryRecord["edits"]>[number];
type ToolContext = Parameters<ToolExecutionApi["commit"]>[1];

/** Pit's applied context edits: the entry that carries a rewrite and what it did. */
export const EDIT_KIND = "pit.context-edit";
/** A rewrite staged for the end of the run, applied by the entry that lists it. */
export const PENDING_EDIT_KIND = "pit.context-edit-pending";

export const ELIDED_PREFIX = "[Elided by the model";
export const ELIDED_CALLS_PREFIX = "[Pit: elided tool call";
export const SUMMARY_PREFIX = "[Model summary of ";

export type ContextRole = "user" | "assistant" | "toolResult" | "custom" | "summary";
export type ContextState = "original" | "elided" | "summarized" | "replaced";
export type ContextOperation = "elide" | "summarize";

/** What Pit records with each rewrite, so an outline can say what changed an entry. */
export interface EditProvenance {
  operation: ContextOperation;
  targets: string[];
  /** Summarize: the entry carrying the summary. */
  carrier?: string;
  /** Every entry the rewrite changed. */
  covers: string[];
  reason?: string;
  tokensFreed: number;
}

/** One model-visible entry of the active context. */
export interface ContextItem {
  readonly id: string;
  readonly entry: EntryRecord;
  readonly role: ContextRole;
  /** Messages the model sees now, after edits. */
  readonly messages: readonly Message[];
  readonly tokens: number;
  readonly state: ContextState;
  readonly tools: readonly string[];
  readonly toolCallIds: readonly string[];
  readonly protectedReason?: string;
  /** Summary carriers: the entries the summary replaced. */
  readonly covers?: readonly string[];
}

export interface ContextView {
  /** Model-visible entries in context order, without system entries. */
  readonly items: readonly ContextItem[];
  readonly byId: ReadonlyMap<string, ContextItem>;
  /** Each visible tool result, by the ID of the call it answers. */
  readonly results: ReadonlyMap<string, ContextItem>;
  /** Entries in the active range, whether or not an edit hides them. */
  readonly activeIds: ReadonlySet<string>;
  /** Targets of rewrites staged for the end of the run, by operation. */
  readonly pending: ReadonlyMap<string, ContextOperation>;
  readonly tailId: string | undefined;
  /** Estimated tokens of system entries: the prompt, sections, and tools. */
  readonly systemTokens: number;
  readonly tokens: number;
}

const SCAN_PAGE = 256;
// Assistant messages pi-durable leaves out of the model context.
const EXCLUDED_STOP_REASONS = new Set(["aborted", "error", "deferred"]);
// pi-ai's image estimate, as Pi's token heuristic uses.
const IMAGE_TOKENS = 1_200;

const PROTECTED: Partial<Record<ContextRole, string>> = {
  user: "user message",
  custom: "host message",
  summary: "compaction summary",
};

/** Pi's heuristic: about four characters per token, and a fixed cost per image. */
export function messageTokens(message: Message): number {
  let chars = 0;
  let images = 0;
  const content: unknown = message.content;
  if (typeof content === "string") chars += content.length;
  else if (Array.isArray(content)) {
    for (const block of content as Array<Record<string, unknown>>) {
      if (block.type === "text") chars += String(block.text).length;
      else if (block.type === "thinking") chars += String(block.thinking).length;
      else if (block.type === "toolCall") {
        chars += String(block.name).length + JSON.stringify(block.arguments).length;
      } else if (block.type === "image") images += 1;
    }
  }
  return Math.ceil(chars / 4) + images * IMAGE_TOKENS;
}

export function messagesTokens(messages: readonly Message[]): number {
  return messages.reduce((sum, message) => sum + messageTokens(message), 0);
}

function contributes(message: Message): boolean {
  return !(message.role === "assistant" && EXCLUDED_STOP_REASONS.has(message.stopReason));
}

function roleOf(entry: EntryRecord, message: Message): ContextRole {
  if (entry.kind === "pi.compaction") return "summary";
  if (message.role === "assistant") return "assistant";
  if (message.role === "toolResult") return "toolResult";
  return entry.kind === "pi.user" ? "user" : "custom";
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function provenanceOf(entry: EntryRecord): EditProvenance[] {
  const data = entry.data;
  if (!isRecord(data) || !Array.isArray(data.operations)) return [];
  return data.operations.filter(isRecord) as unknown as EditProvenance[];
}

/** The entries from the newest head marker through the tail, read in one commit. */
async function readActiveRange(
  api: Pick<ToolExecutionApi, "commit" | "conversationId">,
  context: ToolContext,
): Promise<{ head: EntryRecord | undefined; entries: EntryRecord[] }> {
  return api.commit(async (tx) => {
    const head = await tx.latestHeadMarker(api.conversationId);
    const entries: EntryRecord[] = [];
    const query = {
      conversationId: api.conversationId,
      order: "ascending",
      ...(head?.head === undefined ? {} : { minEntryId: head.head }),
    } as const;
    let page = await tx.scanEntries(query, SCAN_PAGE);
    entries.push(...page.items);
    while (page.next !== undefined) {
      page = await tx.scanEntries(query, SCAN_PAGE, page.next);
      entries.push(...page.items);
    }
    return { head, entries };
  }, context);
}

/** The newest edit of each target, what Pit recorded about it, and rewrites still staged. */
function collectEdits(entries: readonly EntryRecord[]) {
  const edits = new Map<EntryId, { edit: ContextEdit; by: EntryRecord }>();
  const provenance = new Map<string, EditProvenance>();
  const pendingEntries: EntryRecord[] = [];
  const applied = new Set<string>();
  for (const entry of entries) {
    for (const edit of entry.edits ?? []) edits.set(edit.target, { edit, by: entry });
    for (const operation of provenanceOf(entry)) {
      for (const target of operation.covers) provenance.set(target, operation);
    }
    if (entry.kind === PENDING_EDIT_KIND) pendingEntries.push(entry);
    if (entry.kind === EDIT_KIND && isRecord(entry.data) && Array.isArray(entry.data.pending)) {
      for (const id of entry.data.pending) applied.add(String(id));
    }
  }
  const pending = new Map<string, ContextOperation>();
  for (const entry of pendingEntries) {
    if (applied.has(String(entry.id))) continue;
    for (const operation of provenanceOf(entry)) {
      for (const target of operation.covers) {
        pending.set(target, operation.operation);
      }
    }
  }
  return { edits, provenance, pending };
}

/**
 * The active context as pi-durable assembles it: the newest head marker, then the non-head entries
 * from its head through the tail, each contributing its messages after the newest edit that targets
 * it. `callId` is the running tool call; its turn is protected.
 */
export async function readContextView(
  api: Pick<ToolExecutionApi, "commit" | "conversationId">,
  context: ToolContext,
  callId: string,
): Promise<ContextView> {
  const { head, entries } = await readActiveRange(api, context);
  const { edits, provenance, pending } = collectEdits(entries);
  const active = [
    ...(head ? [head] : []),
    ...entries.filter((entry) => entry.head === undefined && entry.id !== head?.id),
  ];
  const items: ContextItem[] = [];
  let systemTokens = 0;
  let currentTurn = false;
  for (const entry of active) {
    const original = (entry.model ?? []).filter(contributes);
    const edited = edits.get(entry.id);
    const messages =
      edited === undefined ? original : edited.edit.action === "omit" ? [] : edited.edit.messages;
    const first = original[0];
    if (first === undefined) continue;
    if (first.role === "system") {
      systemTokens += messagesTokens(messages);
      continue;
    }
    if (messages.length === 0) continue;
    const id = String(entry.id);
    const role = roleOf(entry, first);
    const calls =
      first.role === "assistant"
        ? first.content.flatMap((block) => (block.type === "toolCall" ? [block] : []))
        : [];
    if (calls.some((call) => call.id === callId)) currentTurn = true;
    const operation = edited ? provenance.get(id) : undefined;
    const state: ContextState = !edited
      ? "original"
      : operation?.operation === "elide"
        ? "elided"
        : operation?.operation === "summarize"
          ? "summarized"
          : "replaced";
    const protectedReason = currentTurn ? "current turn" : PROTECTED[role];
    items.push({
      id,
      entry,
      role,
      messages,
      tokens: messagesTokens(messages),
      state,
      tools: first.role === "toolResult" ? [first.toolName] : calls.map((call) => call.name),
      toolCallIds: first.role === "toolResult" ? [first.toolCallId] : calls.map((call) => call.id),
      ...(protectedReason ? { protectedReason } : {}),
      ...(operation?.carrier === id ? { covers: operation.covers } : {}),
    });
  }
  const byId = new Map(items.map((item) => [item.id, item]));
  const results = new Map(
    items.flatMap((item) =>
      item.role === "toolResult" ? item.toolCallIds.map((call) => [call, item] as const) : [],
    ),
  );
  return {
    items,
    byId,
    results,
    activeIds: new Set(active.map((entry) => String(entry.id))),
    pending,
    tailId: entries.length === 0 ? undefined : String(entries.at(-1)?.id),
    systemTokens,
    tokens: systemTokens + items.reduce((sum, item) => sum + item.tokens, 0),
  };
}

